mapper.select:
SELECT s.id, s.emp_id, s.month, s.basic_salary AS basicSalary, s.food_subsidy AS foodSubsidy, s.traffic_subsidy AS trafficSubsidy, s.housing_subsidy AS housingSubsidy, s.level_subsidy AS levelSubsidy, s.late_fine AS lateFine, s.tax, s.actual_salary AS actualSalary, e.name AS name, d.dept_name AS deptName FROM salary s LEFT JOIN employee e ON s.emp_id = e.id LEFT JOIN dept d ON e.dept_id = d.id
AND DATE_FORMAT(s.month, '%Y') = #{year}
AND DATE_FORMAT(s.month, '%Y-%m') = #{month}
AND d.dept_name LIKE CONCAT('%', #{dept}, '%')
AND e.name LIKE CONCAT('%', #{name}, '%')
AND s.emp_id = #{empId}
ORDER BY s.month ${sortOrder}

